#!/usr/bin/env node
/** Self-contained TypeScript bootstrap. No npm dependencies. Read --help before running. */
import { existsSync, readFileSync, writeFileSync, mkdirSync, renameSync, chmodSync, lstatSync, readdirSync, rmSync, statfsSync, copyFileSync } from 'node:fs';
import { homedir, totalmem } from 'node:os';
import { dirname, join, resolve, isAbsolute, sep, basename } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createHash, randomBytes } from 'node:crypto';
import { gunzipSync } from 'node:zlib';
import { spawn, spawnSync } from 'node:child_process';
import { createServer } from 'node:net';
import { parseArgs } from 'node:util';

const VERSION = '2026-09-27.1';
const DEFAULT_ROOT = join(homedir(), '__code__', 'agent-scrpts');
const OPTIONS = {
  help:{type:'boolean',short:'h'}, 'dry-run':{type:'boolean'}, 'scaffold-only':{type:'boolean'},
  root:{type:'string'}, 'mlx-only':{type:'boolean'}, 'with-decider-2b':{type:'boolean'},
  'no-github':{type:'boolean'}, 'no-service':{type:'boolean'}, 'github-owner':{type:'string'},
} as const;
const HELP = `agent-scrpts bootstrap ${VERSION}

  node bootstrap.ts                 Complete local install + private GitHub push
  node bootstrap.ts --dry-run       Show intended operations without changing anything
  node bootstrap.ts --mlx-only      Install the three Laya MLX variants, no Decider
  node bootstrap.ts --with-decider-2b  Also install Decider 2B (requires >=16 GiB RAM)
  node bootstrap.ts --root PATH     Override ~/__code__/agent-scrpts/
  node bootstrap.ts --github-owner OWNER  Default: your authenticated personal account
  node bootstrap.ts --no-github     Explicitly omit GitHub creation/push
  node bootstrap.ts --no-service    Install files/models without starting a login service
  node bootstrap.ts --scaffold-only --root PATH  Emit source only; no configuration/deps/GitHub

Normal mode requires Apple Silicon, macOS >=15 and Node >=22.18 (or >=23.6).
Node and the existing oMLX installation are never replaced or modified.
Homebrew/system installation and GitHub login may require your native approval.
Never run this script with sudo. Re-run to resume; existing source is preserved.
The ZIP does not contain weights. Installation downloads pinned snapshots.
`;
function say(s:string):void { process.stdout.write(s+'\n'); }
function warn(s:string):void { process.stderr.write('Warning: '+s+'\n'); }
function err(e:unknown):string { return e instanceof Error ? e.message : String(e); }
function assert(ok:unknown,message:string):asserts ok { if(!ok) throw new Error(message); }
function hash(data:string|Buffer):string {return createHash('sha256').update(data).digest('hex');}
function atomic(path:string,text:string,mode=0o600):void {
  mkdirSync(dirname(path),{recursive:true,mode:0o700});
  const temp=path+'.'+process.pid+'.'+randomBytes(4).toString('hex')+'.tmp';
  writeFileSync(temp,text,{mode});renameSync(temp,path);chmodSync(path,mode);
}
function json(path:string):any{return JSON.parse(readFileSync(path,'utf8'));}
function command(cmd:string,args:string[],opts:{cwd?:string;inherit?:boolean;allowFailure?:boolean;input?:string;env?:NodeJS.ProcessEnv}={}):string {
  const r=spawnSync(cmd,args,{cwd:opts.cwd,env:opts.env??process.env,encoding:'utf8',stdio:opts.inherit?'inherit':'pipe',input:opts.input,maxBuffer:16*1024*1024});
  if(r.error||r.status!==0){if(opts.allowFailure)return '';throw new Error(`${basename(cmd)} ${args.slice(0,3).join(' ')} failed: ${r.error?.message??r.stderr??'exit '+r.status}`);}
  return (r.stdout??'').trim();
}
function succeeds(cmd:string,args:string[]):boolean{const r=spawnSync(cmd,args,{stdio:'ignore'});return !r.error&&r.status===0;}
async function capture(cmd:string,args:string[],input?:string):Promise<string> {
  return new Promise((resolve,reject)=>{
    const child=spawn(cmd,args,{stdio:['pipe','pipe','inherit']});const chunks:Buffer[]=[];let size=0;
    child.on('error',reject);child.stdout.on('data',(d:Buffer)=>{size+=d.length;if(size>16*1024*1024){child.kill();reject(new Error('Command output exceeded the safety limit.'));}else chunks.push(d);});
    child.on('close',code=>code===0?resolve(Buffer.concat(chunks).toString('utf8').trim()):reject(new Error(`${basename(cmd)} ${args.slice(0,2).join(' ')} exited ${code}.`)));
    child.stdin.on('error',()=>{});child.stdin.end(input??'');
  });
}
async function get(url:string):Promise<Response> {
  assert(url.startsWith('https://'),'Only HTTPS downloads are accepted.');
  const r=await fetch(url,{headers:{'User-Agent':'agent-scrpts-bootstrap/'+VERSION},signal:AbortSignal.timeout(90_000)});
  if(!r.ok)throw new Error(`Download failed: HTTP ${r.status} for ${url}`);return r;
}
function expand(path:string):string {return resolve(path==='~'?homedir():path.startsWith('~/')?join(homedir(),path.slice(2)):path);}
function safeDestination(root:string,relative:string):string {
  assert(!isAbsolute(relative)&&!relative.split(/[\\/]/).includes('..'),'Unsafe embedded file path.');
  const target=resolve(root,relative);assert(target.startsWith(root+sep),'Embedded path escaped repository.');
  let p=target;
  while(p!==root){if(existsSync(p))assert(!lstatSync(p).isSymbolicLink(),'Refusing to write through a symlink: '+p);p=dirname(p);}
  return target;
}
function writeNew(root:string,relative:string,content:string,changed:Set<string>):void {
  const p=safeDestination(root,relative);if(existsSync(p)){assert(lstatSync(p).isFile(),'Expected a regular file: '+p);return;}
  atomic(p,content,0o644);changed.add(relative);
}
function updateManaged(path:string,body:string,id:string,backupDir:string,kind:'markdown'|'shell'='markdown'):void {
  if(existsSync(path))assert(!lstatSync(path).isSymbolicLink(),'Refusing to edit a symlinked configuration file: '+path);
  const old=existsSync(path)?readFileSync(path,'utf8'):'';
  const start=kind==='markdown'?`<!-- BEGIN ${id} -->`:`# BEGIN ${id}`;
  const end=kind==='markdown'?`<!-- END ${id} -->`:`# END ${id}`;
  const block=start+'\n'+body.trimEnd()+'\n'+end;
  const a=old.indexOf(start),b=old.indexOf(end);
  assert((a<0&&b<0)||(a>=0&&b>a&&old.indexOf(start,a+start.length)<0&&old.indexOf(end,b+end.length)<0),'Malformed or duplicate managed markers in '+path);
  const next=a>=0?old.slice(0,a)+block+old.slice(b+end.length):(old.trimEnd()?old.trimEnd()+'\n\n':'')+block+'\n';
  if(next===old)return;
  if(existsSync(path)){mkdirSync(backupDir,{recursive:true,mode:0o700});const dest=join(backupDir,basename(path)+'.'+Date.now()+'.'+randomBytes(3).toString('hex'));copyFileSync(path,dest);chmodSync(dest,0o600);}
  atomic(path,next,existsSync(path)?lstatSync(path).mode&0o777:0o600);
}
const quote=(s:string)=>"'"+s.replaceAll("'","'\\''")+"'";
async function freePort(start:number):Promise<number> {
  for(let p=start;p<start+30;p++) {
    const free=await new Promise<boolean>(resolve=>{const s=createServer();s.once('error',()=>resolve(false));s.listen(p,'127.0.0.1',()=>s.close(()=>resolve(true)));});
    if(free)return p;
  } throw new Error('No free loopback port in the installation range.');
}
async function ensureTools(needGitHub:boolean,state:string,report:any):Promise<void> {
  process.env.PATH=[join(homedir(),'.local/bin'),'/opt/homebrew/bin','/usr/local/bin',process.env.PATH??'/usr/bin:/bin'].join(':');
  const needed=['git','uv',...(needGitHub?['gh']:[])].filter(c=>!succeeds(c,['--version']));
  if(!needed.length)return;
  if(!succeeds('brew',['--version'])){
    say('Installing Homebrew through its official installer; native approval may be requested.');
    const url='https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh';const text=await(await get(url)).text();
    const p=join(state,'homebrew-install.sh');atomic(p,text,0o700);report.homebrewInstaller={url,sha256:hash(text)};
    command('/bin/bash',[p],{inherit:true});
  }
  assert(succeeds('brew',['--version']),'Homebrew is not available after installation. Finish its native prerequisites and rerun.');
  for(const name of needed){say('Installing '+name+' with Homebrew.');command('brew',['install',name],{inherit:true});assert(succeeds(name,['--version']),name+' is still unavailable.');}
}
async function runtime(family:string,root:string,state:string,changed:Set<string>):Promise<string> {
  const env=join(state,'envs',family),python=join(env,'bin','python');
  if(!existsSync(python))command('uv',['venv','--python','3.12',env],{inherit:true});
  const lock=join(root,'runtime',`requirements-${family}.lock`);
  if(!existsSync(lock)){
    command('uv',['pip','compile',join(root,'runtime',`requirements-${family}.in`),'--python',python,'--generate-hashes','--no-header','--output-file',lock],{inherit:true});
    changed.add(`runtime/requirements-${family}.lock`);
  }
  command('uv',['pip','sync','--python',python,'--require-hashes',lock],{inherit:true});
  if(family==='decider'){
    const app=join(root,'runtime','requirements-decider-app.lock');
    if(!existsSync(app)){
      const data=await(await get('https://pypi.org/pypi/decider-ai/1.5.0/json')).json() as any;
      const wheel=data.urls.find((f:any)=>f.packagetype==='bdist_wheel'&&f.filename.endsWith('py3-none-any.whl'));
      assert(wheel&&/^[a-f0-9]{64}$/.test(wheel.digests.sha256),'Unable to resolve the pinned Decider wheel hash.');
      atomic(app,`# Mac adapter: dependencies are managed in requirements-decider.lock.\ndecider-ai==1.5.0 --hash=sha256:${wheel.digests.sha256}\n`,0o644);changed.add('runtime/requirements-decider-app.lock');
    }
    command('uv',['pip','install','--python',python,'--no-deps','--require-hashes','-r',app],{inherit:true});
  }
  command(python,['-c',family==='laya'?'import mlx.core; import laya_mlx; import huggingface_hub':'import torch; import mlx.core; from decider.infer import Decider; assert torch.backends.mps.is_available(), "MPS unavailable"'],{inherit:true});
  return python;
}
async function github(root:string,ownerOption:string|undefined,changed:Set<string>,report:any):Promise<void> {
  if(!succeeds('gh',['auth','status','--hostname','github.com'])){
    say('GitHub authentication is needed; complete the browser login.');
    command('gh',['auth','login','--hostname','github.com','--git-protocol','https','--web'],{inherit:true});
  }
  const account=JSON.parse(command('gh',['api','user']));const owner=ownerOption??account.login;
  assert(/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(owner),'Invalid GitHub owner.');
  const remoteName=`${owner}/agent-scrpts`;
  if(!existsSync(join(root,'.git')))command('git',['init','-b','main',root],{inherit:true});
  const git=(...args:string[])=>command('git',['-C',root,...args]);
  assert(git('branch','--show-current')==='main','Primary repository must be on main; no checkout or reset was attempted.');
  if(!command('git',['-C',root,'config','user.name'],{allowFailure:true}))git('config','user.name',account.name||account.login);
  if(!command('git',['-C',root,'config','user.email'],{allowFailure:true}))git('config','user.email',`${account.id}+${account.login}@users.noreply.github.com`);
  let info:any;
  const view=spawnSync('gh',['repo','view',remoteName,'--json','isPrivate,nameWithOwner,url'],{encoding:'utf8'});
  if(view.status===0)info=JSON.parse(view.stdout);
  else {command('gh',['repo','create',remoteName,'--private','--description','Reusable TypeScript agent workflows and local typed classifiers'],{inherit:true});info=JSON.parse(command('gh',['repo','view',remoteName,'--json','isPrivate,nameWithOwner,url']));}
  assert(info.isPrivate===true,'The matching GitHub repository is not private; refusing to push.');
  const existing=command('git',['-C',root,'remote','get-url','origin'],{allowFailure:true});
  const normalize=(url:string)=>url.replace(/^git@github\.com:/,'').replace(/^https:\/\/github\.com\//,'').replace(/\.git$/,'').toLowerCase();
  if(existing)assert(normalize(existing)===remoteName.toLowerCase(),'origin points to a different repository; it was not changed.');
  else git('remote','add','origin',`https://github.com/${remoteName}.git`);
  command('gh',['auth','setup-git','--hostname','github.com'],{inherit:true});
  // Commit only files introduced by this scaffold and its explicit generated lockfiles.
  // Existing modifications and unrelated staged changes remain untouched.
  const files=[...changed].filter(p=>existsSync(join(root,p)));
  if(files.length){git('add','--',...files);const staged=git('diff','--cached','--name-only','--',...files);if(staged)git('commit','--only','-m','Bootstrap reusable agent scripts and local classifier service','--',...files);}
  assert(succeeds('git',['-C',root,'rev-parse','--verify','HEAD']),'There is no commit to push.');
  git('push','--set-upstream','origin','main');
  const confirmed=JSON.parse(command('gh',['repo','view',remoteName,'--json','isPrivate,url']));assert(confirmed.isPrivate,'Private-repository verification failed.');
  report.github={private:true,url:confirmed.url,commit:git('rev-parse','HEAD')};
}

async function main():Promise<void> {
  const {values}=parseArgs({options:OPTIONS,strict:true});
  if(values.help){say(HELP);return;}
  const root=expand(values.root??DEFAULT_ROOT),only=!!values['scaffold-only'];
  assert(!(values['mlx-only']&&values['with-decider-2b']),'--mlx-only and --with-decider-2b cannot be combined.');
  const plan={root,mode:only?'source-only':'complete-install',models:['laya-english','laya-multilingual','laya-typed',...(!values['mlx-only']?['decider-0.8b']:[]),...(values['with-decider-2b']?['decider-2b']:[])],github:!only&&!values['no-github'],loginService:!only&&!values['no-service'],omlx:'unchanged',node:'existing installation',globalInstructions:!only?'append managed Codex block, preserving existing content':'unchanged'};
  if(values['dry-run']){say(JSON.stringify(plan,null,2));return;}
  if(!only){
    assert(process.platform==='darwin'&&process.arch==='arm64','Normal installation requires an Apple Silicon Mac. --scaffold-only is available for source inspection on other systems.');
    assert(process.getuid?.()!==0,'Do not run bootstrap as root or with sudo.');
    const [major,minor]=process.versions.node.split('.').map(Number);assert((major===22&&minor>=18)||(major===23&&minor>=6)||major>=24,'Use your current Node release (minimum 22.18 / 23.6). Node will not be installed by this script.');
    assert(Number(command('/usr/bin/sw_vers',['-productVersion']).split('.')[0])>=15,'This bootstrap targets macOS 15 or later, matching the current supported Homebrew baseline.');
    if(values['with-decider-2b'])assert(totalmem()>=16*1024**3,'The optional 2B profile requires at least 16 GiB RAM.');
  }
  assert(root!==homedir()&&root!==dirname(root),'Choose a dedicated repository directory.');
  if(existsSync(root)){
    assert(lstatSync(root).isDirectory()&&!lstatSync(root).isSymbolicLink(),'Repository root must be a real directory, not a symlink.');
    assert(readdirSync(root).length===0||existsSync(join(root,'.agent-scrpts-scaffold.json')),'Destination is nonempty and is not marked as this scaffold. Nothing was overwritten.');
  }
  mkdirSync(dirname(root),{recursive:true});const lock=root+'.bootstrap.lock';
  try{mkdirSync(lock);}catch{throw new Error(`An installation lock exists: ${lock}. Inspect owner.json and verify that process is no longer running before manually removing a stale lock.`);}
  writeFileSync(join(lock,'owner.json'),JSON.stringify({pid:process.pid,created:new Date().toISOString()}));
  const changed=new Set<string>(),state=join(homedir(),'.local','share','agent-scrpts');
  let report:any={version:VERSION,started:new Date().toISOString(),plan,completed:[],failures:[],warnings:[]};
  const reportPath=join(state,'setup-report.json');
  const stage=async(name:string,action:()=>Promise<void>|void)=>{
    say('\n'+name+'…');try{await action();report.completed.push(name);}catch(e){report.failures.push({stage:name,error:err(e)});warn(name+': '+err(e));}
    atomic(reportPath,JSON.stringify(report,null,2)+'\n');
  };
  try {
    mkdirSync(root,{recursive:true});
    const bytes=Buffer.from(EMBEDDED_PAYLOAD,'base64');assert(hash(bytes)===EMBEDDED_SHA256,'Embedded source checksum mismatch.');
    const files=JSON.parse(gunzipSync(bytes).toString('utf8')) as Record<string,string>;
    for(const [path,text]of Object.entries(files))writeNew(root,path,text,changed);
    writeNew(root,'.agent-scrpts-scaffold.json',JSON.stringify({version:VERSION,format:1},null,2)+'\n',changed);
    const self=fileURLToPath(import.meta.url);if(resolve(self)!==join(root,'bootstrap.ts'))writeNew(root,'bootstrap.ts',readFileSync(self,'utf8'),changed);
    say('Source repository: '+root);
    if(only){say('Source-only mode completed; dependencies, home configuration and GitHub were not touched.');return;}
    mkdirSync(state,{recursive:true,mode:0o700});
    const introducedPath=join(state,'introduced-source.json');
    const introduced=existsSync(introducedPath)?json(introducedPath):{};
    for(const [relative,text]of Object.entries(files))if(existsSync(join(root,relative))&&hash(readFileSync(join(root,relative)))===hash(text))introduced[relative]=hash(text);
    if(existsSync(join(root,'bootstrap.ts'))&&hash(readFileSync(join(root,'bootstrap.ts')))===hash(readFileSync(self)))introduced['bootstrap.ts']=hash(readFileSync(self));
    introduced['.agent-scrpts-scaffold.json']=hash(readFileSync(join(root,'.agent-scrpts-scaffold.json')));
    for(const relative of changed)introduced[relative]=hash(readFileSync(join(root,relative)));
    atomic(introducedPath,JSON.stringify(introduced,null,2)+'\n');
    // On resume, include only byte-identical source files this installer introduced.
    for(const [relative,digest] of Object.entries(introduced)){
      const file=safeDestination(root,relative);
      if(existsSync(file)&&lstatSync(file).isFile()&&hash(readFileSync(file))===digest)changed.add(relative);
    }
    report.hardware={arch:process.arch,macOS:command('/usr/bin/sw_vers',['-productVersion']),memoryGiB:Math.round(totalmem()/1024**3),node:process.versions.node};
    await ensureTools(!values['no-github'],state,report);
    const support=await import(pathToFileURL(join(root,'src','support.ts')).href);
    say('\nRunning source tests…');support.testRepository(root);report.completed.push('source-tests');
    const configPath=join(homedir(),'.config','agent-scrpts','config.json');
    const previous=existsSync(configPath)?json(configPath):null;
    if(previous)assert(previous.root===root,'Another root is already configured in '+configPath+'; it was not replaced.');
    const svc=await import(pathToFileURL(join(root,'src','service.ts')).href);
    if(existsSync(svc.plistPath())){
      assert(readFileSync(svc.plistPath(),'utf8').includes('agent-scrpts-managed'),'An unmanaged service uses this label; it was not stopped.');
      svc.service('stop');await new Promise(r=>setTimeout(r,1200));
    }
    const fs=statfsSync(state),free=Number(fs.bavail)*Number(fs.bsize);
    if(free<6*1024**3){const warning='Less than 6 GiB free disk space; model/runtime downloads may fail. Existing cached weights can be reused.';report.warnings.push(warning);warn(warning);}
    say('\nPreparing managed Python 3.12…');command('uv',['python','install','3.12'],{inherit:true});
    const python:Record<string,string>={};
    await stage('Laya MLX runtime',async()=>{python.laya=await runtime('laya',root,state,changed);});
    if(!values['mlx-only'])await stage('Decider MPS runtime',async()=>{python.decider=await runtime('decider',root,state,changed);});
    const low=totalmem()<16*1024**3;
    const recipes:any[]=[
      {id:'laya-english',family:'laya',repo:'aac6fef/laya-mlx',description:'Short English text classification.',maxTokens:512,maxChoices:16},
      {id:'laya-multilingual',family:'laya',repo:'aac6fef/laya-multilingual-mlx',description:'Non-English and multilingual semantic decisions.',maxTokens:1024,maxChoices:16},
      {id:'laya-typed',family:'laya',repo:'aac6fef/laya-typed-decisions-mlx',description:'English workflow judgments and typed decision rubrics.',maxTokens:1024,maxChoices:16},
      ...(!values['mlx-only']?[{id:'decider-0.8b',family:'decider',repo:'Mapika/decider-0.8b',description:'Longer text and complex semantic choice or scoring.',maxTokens:low?2048:4096,maxChoices:255}]:[]),
      ...(values['with-decider-2b']?[{id:'decider-2b',family:'decider',repo:'Mapika/decider-2b',description:'Larger specialist for difficult text decisions; slower.',maxTokens:4096,maxChoices:255}]:[]),
    ];
    const modelLockPath=join(root,'model-lock.json');const locks=existsSync(modelLockPath)?json(modelLockPath):{format:1,models:{}};
    assert(locks.format===1&&locks.models,'Unsupported model lock format.');
    const models:any[]=[];
    for(const recipe of recipes){
      let m:any={...recipe,revision:'',path:'',enabled:false};
      await stage('Model '+recipe.id,async()=>{
        assert(python[recipe.family],'Required inference environment did not install.');
        let pin=locks.models[recipe.id];
        if(!pin){const data=await(await get(`https://huggingface.co/api/models/${recipe.repo}`)).json() as any;assert(/^[a-f0-9]{40}$/.test(data.sha),'No immutable revision returned for '+recipe.repo);pin={repo:recipe.repo,revision:data.sha};locks.models[recipe.id]=pin;atomic(modelLockPath,JSON.stringify(locks,null,2)+'\n',0o644);changed.add('model-lock.json');}
        assert(pin.repo===recipe.repo&&/^[a-f0-9]{40}$/.test(pin.revision),'Invalid/mismatched model lock: '+recipe.id);
        const text=await capture(python[recipe.family],[join(root,'runtime','worker.py'),'--download'],JSON.stringify(pin));
        const data=JSON.parse(text.split('\n').filter(Boolean).at(-1)!);
        assert(typeof data.path==='string'&&existsSync(data.path)&&Object.keys(data.sha256??{}).some(k=>k.endsWith('.safetensors')),'Downloaded snapshot does not contain verified safetensors weights.');
        if(pin.sha256)assert(JSON.stringify(pin.sha256)===JSON.stringify(data.sha256),'The snapshot checksum set differs from its recorded model lock.');
        const updated={...pin,sha256:data.sha256,bytes:data.bytes};
        if(JSON.stringify(updated)!==JSON.stringify(pin)){locks.models[recipe.id]=updated;atomic(modelLockPath,JSON.stringify(locks,null,2)+'\n',0o644);changed.add('model-lock.json');}
        m={...recipe,revision:pin.revision,path:data.path,enabled:true};
      });
      if(!m.enabled)m.error='Installation incomplete; read setup-report.json and rerun.';
      models.push(m);
    }
    // Retain user-added models and deliberate configuration while refreshing requested snapshots.
    for(const m of models){
      const old=previous?.models?.find((p:any)=>p.id===m.id);
      if(old&&m.enabled){m.maxTokens=Math.min(m.maxTokens,old.maxTokens??m.maxTokens);m.maxChoices=Math.min(m.maxChoices,old.maxChoices??m.maxChoices);if(old.enabled===false&&!old.error)m.enabled=false;}
    }
    for(const old of previous?.models??[])if(!recipes.some(r=>r.id===old.id)&&!(values['mlx-only']&&old.family==='decider'))models.push(old);
    for(const [family,path]of Object.entries(previous?.python??{}))if(!python[family]&&typeof path==='string'&&existsSync(path))python[family]=path;
    const tokenFile=join(dirname(configPath),'token');if(!existsSync(tokenFile))atomic(tokenFile,randomBytes(32).toString('hex')+'\n');
    assert(!lstatSync(tokenFile).isSymbolicLink(),'Token file must not be a symlink.');chmodSync(tokenFile,0o600);
    const config:any={...(previous??{}),version:1,root,stateDir:state,tokenFile,host:'127.0.0.1',port:previous?.port??await freePort(7331),python,models,router:previous?.router??'laya-multilingual',
      requestTimeoutMs:previous?.requestTimeoutMs??120000,maxQueue:previous?.maxQueue??16,maxBodyBytes:previous?.maxBodyBytes??262144,idleSeconds:previous?.idleSeconds??120,
      memoryBudgetBytes:Math.floor(Math.min(totalmem()*.35,4*1024**3)),lowMemory:low};
    assert(Number.isInteger(config.port)&&config.port>=1024&&config.port<=65535,'Invalid existing port.');
    atomic(configPath,JSON.stringify(config,null,2)+'\n');
    await stage('Real model smoke checks',async()=>{
      const {smokeModels}=await import(pathToFileURL(join(root,'src','smoke.ts')).href);report.inference=await smokeModels(config);
      for(const result of report.inference){
        say(`${result.model}: ${result.operational?'operational; warm median '+result.warmMedianMs.toFixed(1)+' ms':'FAILED: '+result.error}`);
        if(!result.operational){const m=config.models.find((m:any)=>m.id===result.model);m.enabled=false;m.error=result.error;report.failures.push({stage:'inference:'+result.model,error:result.error});}
        else if(!result.sanity.billingSelected||!result.sanity.refundAboveHalf){const warning=`${result.model} returned valid output but missed a tiny sanity label; do not assume task accuracy.`;report.warnings.push(warning);warn(warning);}
      }
      atomic(configPath,JSON.stringify(config,null,2)+'\n');
      assert(config.models.some((m:any)=>m.enabled),'No model passed actual inference. Source is preserved; resolve the runtime failure before using classifiers.');
      if(!config.models.some((m:any)=>m.id===config.router&&m.enabled)){report.failures.push({stage:'routing-classifier',error:'The configured routing classifier is unavailable; only the reported deterministic routing fallback can be used.'});}
    });
    await stage('CLI and global agent instructions',()=>{
      const bin=join(homedir(),'.local','bin','ascr'),backups=join(state,'backups');
      if(existsSync(bin))assert(!lstatSync(bin).isSymbolicLink()&&readFileSync(bin,'utf8').includes('agent-scrpts-managed'),'An unmanaged ascr command exists; it was not replaced.');
      atomic(bin,`#!/bin/sh\n# agent-scrpts-managed\nexport ASCR_CONFIG=${quote(configPath)}\nexec ${quote(process.execPath)} --experimental-strip-types --disable-warning=ExperimentalWarning ${quote(join(root,'src','cli.ts'))} "$@"\n`,0o755);
      const pathBody='case ":$PATH:" in\n  *":$HOME/.local/bin:"*) ;;\n  *) export PATH="$HOME/.local/bin:$PATH" ;;\nesac';
      const zdot=process.env.ZDOTDIR?expand(process.env.ZDOTDIR):homedir();
      for(const name of ['.zprofile','.zshrc'])updateManaged(join(zdot,name),pathBody,'agent-scrpts-path',backups,'shell');
      if((process.env.SHELL??'').endsWith('/bash'))for(const name of ['.bash_profile','.bashrc'])updateManaged(join(homedir(),name),pathBody,'agent-scrpts-path',backups,'shell');
      const agents=readFileSync(join(root,'docs','global-agents.md'),'utf8').replaceAll('@@ROOT@@',root).replaceAll('@@URL@@',`http://127.0.0.1:${config.port}`);
      const codex=process.env.CODEX_HOME?expand(process.env.CODEX_HOME):join(homedir(),'.codex');
      updateManaged(join(codex,'AGENTS.md'),agents,'agent-scrpts-global',backups);
      if(existsSync(join(codex,'AGENTS.override.md')))updateManaged(join(codex,'AGENTS.override.md'),agents,'agent-scrpts-global',backups);
      report.cli=bin;report.globalInstructions=join(codex,'AGENTS.md');
    });
    if(!values['no-service'])await stage('Login service and authenticated health check',async()=>{
      assert(config.models.some((m:any)=>m.enabled),'No operational models; service was not started.');
      svc.installService(config,configPath);svc.service('start');
      let health:any,last='';
      for(let i=0;i<40;i++){try{health=await support.api('/health',undefined,config,2000);break;}catch(e){last=err(e);await new Promise(r=>setTimeout(r,500));}}
      assert(health,'Service did not become healthy: '+last);report.service={endpoint:`http://127.0.0.1:${config.port}`,health};
      const {SMOKE}=await import(pathToFileURL(join(root,'src','smoke.ts')).href);
      report.routingCheck=await support.api('/v1/route',{...SMOKE,task:'Customer request triage',language:'en'},config);
      assert(config.models.some((m:any)=>m.id===report.routingCheck.selected&&m.enabled),'The live router did not select an enabled model.');
      if(report.routingCheck.mode==='fallback'){const warning='The live routing check used its reported deterministic fallback: '+report.routingCheck.reason;report.warnings.push(warning);warn(warning);}
    });
    // Retain the list for retry after GitHub/auth failures, without sweeping unrelated files.
    const pending=join(state,'pending-scaffold-files.json');const prior=existsSync(pending)?json(pending):[];
    for(const p of prior){
      if(typeof p!=='string')continue;
      if((files[p]!==undefined||p==='bootstrap.ts'||p==='.agent-scrpts-scaffold.json')&&introduced[p]&&existsSync(safeDestination(root,p))&&hash(readFileSync(join(root,p)))===introduced[p])changed.add(p);
      if(p==='model-lock.json'||/^runtime\/requirements-[a-z-]+\.lock$/.test(p))changed.add(p);
    }
    // Generated locks are this installer's own artifacts; retain them across earlier failures.
    for(const p of ['model-lock.json',...readdirSync(join(root,'runtime')).filter(f=>/^requirements-[a-z-]+\.lock$/.test(f)).map(f=>'runtime/'+f)])if(existsSync(join(root,p)))changed.add(p);
    atomic(pending,JSON.stringify([...changed])+'\n');
    if(!values['no-github'])await stage('Private GitHub repository, commit and push',async()=>{await github(root,values['github-owner'],changed,report);atomic(pending,'[]\n');});
    else if(!existsSync(join(root,'.git')))command('git',['init','-b','main',root],{inherit:true});
    report.finished=new Date().toISOString();report.complete=report.failures.length===0;atomic(reportPath,JSON.stringify(report,null,2)+'\n');
    say('\n'+JSON.stringify({complete:report.complete,root,cli:report.cli,service:report.service?.endpoint,github:report.github,models:config.models.map((m:any)=>({id:m.id,enabled:m.enabled})),report:reportPath,failures:report.failures},null,2));
    say('\nOpen a new terminal for ascr, and a new Codex session for the global instructions.');
    if(report.failures.length)process.exitCode=2;
  }catch(e){
    if(!only){report.failures.push({stage:'bootstrap',error:err(e)});report.complete=false;try{atomic(reportPath,JSON.stringify(report,null,2)+'\n');}catch{}}
    throw e;
  }finally{rmSync(lock,{recursive:true,force:true});}
}

