const EMBEDDED_PAYLOAD = '';
const EMBEDDED_SHA256 = 'e158adfb696d5eb850c230760711dddb4a5682596e7bdd8a0693c99abdeed4ec';
export { safeDestination, updateManaged, writeNew, hash, main };
if(process.argv[1] && resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try { await main(); } catch(e) { process.stderr.write('\nSetup stopped: '+err(e)+'\nExisting work was preserved. Resolve the reported issue and rerun the same command.\n'); process.exitCode=1; }
}
